<!-- components/notifications/ChatNotifications.vue -->
<template>
  <v-card class="chat-notifications-card" :style="cardStyle">
    <!-- Header -->
    <div class="chat-header pa-3">
      <v-icon color="primary" class="mr-2">mdi-message-text</v-icon>
      <span class="font-weight-bold">New Messages</span>
      <v-spacer></v-spacer>
      <v-chip small color="pink" dark>{{ count }}</v-chip>
      <v-btn icon small @click="$emit('close')" class="ml-2">
        <v-icon>mdi-close</v-icon>
      </v-btn>
    </div>

    <v-divider></v-divider>

    <!-- List -->
    <v-list class="py-0" v-if="notifications.length > 0">
      <v-list-item
        v-for="(msg, index) in notifications"
        :key="msg._id || index"
        @click="$emit('select', msg, index)"
        class="notification-item"
      >
        <v-list-item-avatar>
          <v-badge
            dot
            color="success"
            bottom
            offset-x="10"
            offset-y="10"
          >
            <v-avatar size="48">
              <v-img
                :src="getSenderImage(msg)"
                @error="handleImageError"
              />
            </v-avatar>
          </v-badge>
        </v-list-item-avatar>

        <v-list-item-content>
          <div class="d-flex justify-space-between">
            <span class="font-weight-bold text-truncate" style="max-width: 150px;">
              {{ getSenderName(msg) }}
            </span>
            <v-chip x-small color="primary" dark v-if="msg.messageCount > 1">
              +{{ msg.messageCount }}
            </v-chip>
          </div>
          <div class="text-truncate grey--text text--darken-1">
            {{ getMessagePreview(msg) }}
          </div>
          <div class="caption grey--text mt-1">
            {{ formatTime(msg.timestamp || msg.createdAt) }}
          </div>
        </v-list-item-content>
      </v-list-item>
    </v-list>

    <!-- Empty -->
    <div v-else class="text-center pa-8">
      <v-icon size="64" color="grey lighten-2">mdi-inbox</v-icon>
      <p class="grey--text mt-2">No new messages</p>
    </div>

    <!-- Footer -->
    <v-divider v-if="notifications.length > 0"></v-divider>
    <v-card-actions v-if="notifications.length > 0">
      <v-btn small text color="primary" block @click="$emit('mark-all')">
        <v-icon left small>mdi-check-all</v-icon>
        Mark All as Read
      </v-btn>
    </v-card-actions>
  </v-card>
</template>

<script>
import serverUrl from '@/config';

export default {
  props: {
    notifications: {
      type: Array,
      default: () => []
    },
    count: {
      type: Number,
      default: 0
    }
  },
  computed: {
    cardStyle() {
      return {
        position: 'fixed',
        top: '70px',
        right: '20px',
        'z-index': 1000,
        'min-width': '320px',
        'max-width': '400px',
        'max-height': '500px',
        'overflow-y': 'auto',
        'border-radius': '16px'
      };
    }
  },
  methods: {
    getSenderImage(msg) {
      const senderId = msg.senderId || msg.from?._id;
      return `${serverUrl}/profile-image/${senderId}.PNG`;
    },
    getSenderName(msg) {
      return msg.senderName || msg.from?.name || 'Unknown';
    },
    getMessagePreview(msg) {
      if (msg.messageType === 'image') return '📷 Photo';
      if (msg.messageType === 'video') return '🎬 Video';
      return msg.text?.substring(0, 50) || msg.msg?.substring(0, 50) || 'New message';
    },
    formatTime(timestamp) {
      if (!timestamp) return 'Just now';
      const date = new Date(timestamp);
      const now = new Date();
      const diff = Math.floor((now - date) / 60000);
      if (diff < 1) return 'Just now';
      if (diff < 60) return `${diff}m ago`;
      if (diff < 1440) return `${Math.floor(diff / 60)}h ago`;
      return `${Math.floor(diff / 1440)}d ago`;
    },
    handleImageError(event) {
      event.target.src = require('@/assets/avatar.png');
    }
  }
}
</script>

<style scoped>
.chat-notifications-card {
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.chat-header {
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
}

.notification-item {
  transition: all 0.3s;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

.notification-item:hover {
  background: rgba(33, 150, 243, 0.05);
  transform: translateX(5px);
}
</style>