<!-- components/notifications/PostNotifications.vue -->
<template>
  <v-card class="notifications-card" :style="cardStyle">
    <v-card-title class="d-flex align-center">
      <v-icon color="primary" class="mr-2">mdi-bell</v-icon>
      <span class="font-weight-bold">New Posts</span>
      <v-spacer></v-spacer>
      <v-btn icon small @click="$emit('close')">
        <v-icon>mdi-close</v-icon>
      </v-btn>
    </v-card-title>

    <v-divider></v-divider>

    <v-list class="py-0">
      <v-list-item
        v-for="post in notifications"
        :key="post.data.post._id"
        @click="$emit('select', post)"
        class="notification-item"
      >
        <v-list-item-avatar>
          <v-img :src="getUserImage(post.data.post.owner._id)" />
        </v-list-item-avatar>

        <v-list-item-content>
          <v-list-item-title>
            <span class="primary--text font-weight-bold">
              {{ post.data.post.owner.name }}
            </span>
            added new post
          </v-list-item-title>
          <v-list-item-subtitle class="text-truncate">
            {{ post.data.post.text }}
          </v-list-item-subtitle>
        </v-list-item-content>
      </v-list-item>
    </v-list>
  </v-card>
</template>

<script>
import serverUrl from '@/config';

export default {
  props: {
    notifications: {
      type: Array,
      default: () => []
    }
  },
  computed: {
    cardStyle() {
      return {
        position: 'fixed',
        top: '70px',
        right: '20px',
        'z-index': 1000,
        'max-width': '400px',
        'max-height': '500px',
        'overflow-y': 'auto'
      };
    }
  },
  methods: {
    getUserImage(userId) {
      return `${serverUrl}/profile-image/${userId}.PNG`;
    }
  }
}
</script>

<style scoped>
.notifications-card {
  border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.notification-item {
  transition: all 0.3s;
}

.notification-item:hover {
  background: rgba(33, 150, 243, 0.05);
}
</style>