<!-- components/search/SearchResults.vue -->
<template>
  <div class="search-results-container">
    <v-card class="search-results-card" elevation="8">
      <!-- Header -->
      <v-card-title class="search-header">
        <v-icon color="white" class="mr-2">mdi-account-search</v-icon>
        <span class="white--text font-weight-bold">Search Results</span>
        <v-spacer></v-spacer>
        <v-btn icon small dark @click="$emit('clear')">
          <v-icon>mdi-close</v-icon>
        </v-btn>
      </v-card-title>

      <v-divider class="divider-white"></v-divider>

      <!-- Results -->
      <v-list class="results-list" v-if="results.length > 0">
        <v-list-item
          v-for="(user, index) in results"
          :key="user.id"
          @click="$emit('select', user.id)"
          class="result-item"
          :style="{ animationDelay: index * 0.1 + 's' }"
        >
          <v-list-item-avatar>
            <v-avatar size="50">
              <v-img
                :src="'data:image/PNG;base64,' + user.image"
                @error="handleImageError"
              />
            </v-avatar>
          </v-list-item-avatar>

          <v-list-item-content>
            <v-list-item-title class="user-name">{{ user.name }}</v-list-item-title>
            <v-list-item-subtitle>
              <v-icon x-small :color="user.online ? 'success' : 'grey'">
                {{ user.online ? 'mdi-circle' : 'mdi-minus-circle' }}
              </v-icon>
              {{ user.online ? 'Online' : 'Offline' }}
            </v-list-item-subtitle>
          </v-list-item-content>

          <v-list-item-action>
            <v-btn small rounded color="primary" dark>
              <v-icon x-small left>mdi-account-arrow-right</v-icon>
              {{user.id === userID ? 'You' : 'View'}}
            </v-btn>
          </v-list-item-action>
        </v-list-item>
      </v-list>

      <!-- Empty -->
      <div v-else class="text-center pa-4">
        <v-icon size="48" color="white">mdi-account-off</v-icon>
        <p class="white--text">No results found</p>
      </div>
    </v-card>
  </div>
</template>

<script>
export default {
  data : () => ({
    userID: localStorage.getItem('userID')
  }),
  created() {
    console.log(this.results)
  },
  props: {
    results: {
      type: Array,
      default: () => []
    }
  },
  methods: {
    handleImageError(event) {
      event.target.src = require('@/assets/avatar.png');
    }
  }
}
</script>

<style scoped>
.search-results-container {
  position: absolute;
  top: 64px;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 450px;
  z-index: 1000;
}

.search-results-card {
  background: linear-gradient(135deg, rgba(21, 101, 192, 0.95) 0%, rgba(75, 98, 162, 0.95) 100%);
  backdrop-filter: blur(20px);
  border-radius: 20px;
  overflow: hidden;
}

.search-header {
  background: rgba(255, 255, 255, 0.1);
}

.divider-white {
  background: rgba(255, 255, 255, 0.2);
}

.results-list {
  max-height: 400px;
  overflow-y: auto;
}

.result-item {
  margin: 4px 12px;
  border-radius: 12px;
  transition: all 0.3s;
}

.result-item:hover {
  background: rgba(255, 255, 255, 0.15);
}
</style>