<template>
  <v-app>
    <!-- صفحة تسجيل الدخول -->
    <router-view v-if="(!isClientAuth && !getAuthAfterLogin)"></router-view>

    <!-- التطبيق الرئيسي -->
    <div id="app" v-else>
      <!-- إشعار المكالمة الواردة -->
      <v-fade-transition>
        <div v-if="isIngoingCall" class="incoming-call-overlay">
          <div class="call-modal">
            <v-row justify="center" class="mb-4">
              <font-awesome-icon
                icon="phone"
                class="fa fa-phone faa-ring animated fa-2x phone-icon"
              />
            </v-row>
            <v-row>
              <v-col class="text-center">
                <v-btn large fab color="success" dark @click="onAnswer" class="answer-btn">
                  <font-awesome-icon icon="phone" class="fa-sm"/>
                </v-btn>
                <div class="btn-label">Accept</div>
              </v-col>
              <v-col class="text-center">
                <v-btn large fab color="error" dark @click="onReject" class="reject-btn">
                  <font-awesome-icon icon="phone-slash" class="fa-sm"/>
                </v-btn>
                <div class="btn-label">Decline</div>
              </v-col>
            </v-row>
            <v-row class="mt-4">
              <v-col class="text-center">
                <div class="caller-info">
                  <v-avatar size="60" class="caller-avatar">
                    <v-img
                      :src="urls + '/profile-image/' + callerId + '.PNG'"
                      @error="handleImageError"
                      :lazy-src="defaultAvatar"
                    />
                  </v-avatar>
                  <div class="caller-name">{{ callerName }}</div>
                  <div class="call-status">Incoming video call...</div>
                </div>
              </v-col>
            </v-row>
          </div>
        </div>
      </v-fade-transition>

      <!-- شريط التطبيق العلوي -->
      <v-app-bar
        app
        :clipped-left="$vuetify.breakpoint.lgAndUp"
        color="primary darken-2"
        dark
        elevate-on-scroll
        height="56"
      >
        <!-- الدرج الجانبي -->
        <CustomNavDrawer :expandd.sync="expanddNav"/>

        

        <!-- الشعار -->
        <v-toolbar-title class="ml-2" style="width: auto;">
          <span
            @click="goHome"
            class="glassbook font-weight-bold text-h6"
            style="cursor: pointer; margin-left: 50px;"
          >
            {{ windowWidth > 500 ? 'Glass Book' : 'GB' }}
          </span>
        </v-toolbar-title>

        <v-spacer></v-spacer>

        <!-- حقل البحث -->
        <v-text-field
          v-if="$route.name === 'Posts' && $vuetify.breakpoint.mdAndUp"
          v-model="keywords"
          flat
          solo-inverted
          hide-details
          clearable
          prepend-inner-icon="mdi-magnify"
          label="Search"
          class="mx-4 search-field"
          style="max-width: 300px;"
          @keydown.enter="searchUser"
        />

        <v-spacer></v-spacer>

        <!-- اسم المستخدم -->
        <v-chip
          v-if="$route.name === 'Posts'"
          @click="onUsername"
          class="user-chip mr-2"
          color="primary lighten-1"
          dark
          small
          pill
        >
          <!-- <v-avatar left size="20">
            <v-img :src="pho" @error="handleImageError"/>
          </v-avatar> -->
          {{ username }}
        </v-chip>

        <!-- أزرار الإشعارات -->
        <v-tooltip bottom>
          <template v-slot:activator="{ on, attrs }">
            <v-badge
              :content="chatNotification"
              :value="chatNotification > 0"
              color="pink"
              overlap
              bordered
            >
              <v-btn
                icon
                v-bind="attrs"
                v-on="on"
                @click="onChatNotificationKIcon"
                class="notification-btn"
              >
                <v-icon>mdi-message-text</v-icon>
              </v-btn>
            </v-badge>
          </template>
          <span>Messages</span>
        </v-tooltip>

        <v-tooltip bottom>
          <template v-slot:activator="{ on, attrs }">
            <v-badge
              :content="friendRequestlength"
              :value="friendRequestlength > 0"
              color="pink"
              overlap
              bordered
            >
              <v-btn
                icon
                v-bind="attrs"
                v-on="on"
                @click="onFriendRequest"
                class="notification-btn"
              >
                <v-icon>mdi-account-plus</v-icon>
              </v-btn>
            </v-badge>
          </template>
          <span>Friend Requests</span>
        </v-tooltip>

        <v-tooltip bottom>
          <template v-slot:activator="{ on, attrs }">
            <v-badge
              :content="postNotification"
              :value="postNotification > 0"
              color="pink"
              overlap
              bordered
            >
              <v-btn
                icon
                v-bind="attrs"
                v-on="on"
                @click="onNotificationKIcon"
                class="notification-btn"
              >
                <v-icon>mdi-bell</v-icon>
              </v-btn>
            </v-badge>
          </template>
          <span>New Posts</span>
        </v-tooltip>

        <!-- صورة الملف الشخصي -->
        <v-menu offset-y left transition="slide-y-transition">
          <template v-slot:activator="{ on, attrs }">
            <v-btn icon v-bind="attrs" v-on="on">
              <v-avatar size="32">
                <v-img :src="pho" @error="handleImageError"/>
              </v-avatar>
            </v-btn>
          </template>
          <v-list dense>
            <!-- <v-list-item @click="onUsername">
              <v-list-item-icon>
                <v-icon>mdi-account</v-icon>
              </v-list-item-icon>
              <v-list-item-title>Profile</v-list-item-title>
            </v-list-item> -->
            <v-list-item @click="upPhoto">
              <v-list-item-icon>
                <v-icon>mdi-camera</v-icon>
              </v-list-item-icon>
              <v-list-item-title>Change Photo</v-list-item-title>
            </v-list-item>
            <v-divider></v-divider>
            <!-- <v-list-item @click="logout">
              <v-list-item-icon>
                <v-icon color="error">mdi-logout</v-icon>
              </v-list-item-icon>
              <v-list-item-title class="error--text">Logout</v-list-item-title>
            </v-list-item> -->
          </v-list>
        </v-menu>
      </v-app-bar>

      <!-- المحتوى الرئيسي -->
      <v-main>
        <!-- حقل البحث للموبايل -->
        <v-text-field
          v-if="$vuetify.breakpoint.smAndDown && $route.name === 'Posts'"
          v-model="keywords"
          flat
          solo-inverted
          hide-details
          prepend-inner-icon="mdi-magnify"
          label="Search"
          class="mx-4 mt-2"
          @keydown.enter="searchUser"
        />

        <!-- نتائج البحث -->
        <SearchResults
          v-if="keywords && searchNewUser.length > 0"
          :results="searchNewUser"
          @select="onSearchNewUSer"
          @clear="clearSearch"
        />

        <!-- إشعارات المنشورات -->
        <PostNotifications
          v-if="openPostNotification"
          :notifications="postNotificationArr"
          @select="onNotifyPost"
          @close="openPostNotification = false"
        />

        <!-- إشعارات المحادثة -->
        <ChatNotifications
          v-if="openChatNotification"
          :notifications="chatNotificationArr"
          :count="chatNotification"
          @select="onNotifyChat"
          @mark-all="markAllAsRead"
          @close="openChatNotification = false"
        />

        <!-- المحتوى الديناميكي -->
        <v-container fluid>
          <v-row>
            <v-col cols="12">
              <router-view :key="$route.fullPath"/>
            </v-col>
          </v-row>
        </v-container>
      </v-main>

      <!-- زر الإضافة العائم -->
      <v-btn
        v-if="$route.name === 'Posts' && $vuetify.breakpoint.smAndDown"
        fab
        dark
        color="pink"
        fixed
        bottom
        right
        class="fab-btn"
        @click="openPostDialog"
      >
        <v-icon>mdi-plus</v-icon>
      </v-btn>

      <!-- حوار المنشور -->
      <v-dialog v-model="dialog" width="800" persistent content-class="rounded-xl">
        <v-card class="rounded-xl">
          <v-card-title class="primary darken-2 white--text">
            Create A Glass Post
            <v-spacer></v-spacer>
            <v-btn icon dark @click="dialog = false">
              <v-icon>mdi-close</v-icon>
            </v-btn>
          </v-card-title>
          <v-card-text class="pt-4">
            <v-row align="center">
              <v-col cols="12">
                <v-textarea
                  v-model="postText"
                  placeholder="What's on your mind?"
                  outlined
                  rows="3"
                  auto-grow
                  counter="25"
                />
              </v-col>
              <v-col cols="12" v-if="previewImage">
                <v-img :src="previewImage" max-height="200" contain class="rounded-lg"/>
              </v-col>
              <v-col cols="12" class="d-flex align-center">
                <v-btn text color="primary" @click="$refs.fileInput.click()">
                  <v-icon left>mdi-image</v-icon>
                  Add Photo
                </v-btn>
                <input
                  ref="fileInput"
                  type="file"
                  accept="image/*"
                  hidden
                  @change="onFileSelected"
                />
                <v-spacer></v-spacer>
                <v-btn text color="grey" @click="dialog = false">Cancel</v-btn>
                <v-btn color="primary" :disabled="!postText && !selectedFile" @click="savePost">
                  Post
                </v-btn>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>
      </v-dialog>

      <!-- حوار المنشور المجدول -->
      <StepperNewPostDialog v-model="showScheduleForm"/>
    </div>
  </v-app>
</template>

<script>
import serverUrl from './config'
import io from "socket.io-client";
import axios from "axios";
import { eventBus } from "./main";
// import Post from "./components/post/post";
import * as types from "./store/types";
import { mapGetters, mapMutations } from "vuex";
import CustomNavDrawer from './components/customNavdrawer/customNavdrawer';
import StepperNewPostDialog from './components/custom-new-post/stepperNewPostDialog.vue'
import SearchResults from './components/search/SearchResults.vue'
import PostNotifications from './components/notifications/PostNotifications.vue'
import ChatNotifications from './components/notifications/ChatNotifications.vue'

export default {
  name: "App",
  components: {
    // "notify-post": Post,
    CustomNavDrawer,
    StepperNewPostDialog,
    SearchResults,
    PostNotifications,
    ChatNotifications
  },

  data: () => ({
    dialog: false,
    drawer: null,
    selectedFile: null,
    postText: "",
    previewImage: null,
    socket: null,
    photo: null,
    windowWidth: window.innerWidth,
    keywords: "",
    searchNewUser: [],
    username: "",
    postNotification: 0,
    openPostNotification: false,
    postNotificationArr: [],
    dialog2: false,
    notifypostImage: null,
    notifypostName: null,
    notifypostId: null,
    notifypostCommentsArr: [],
    notifypostLikeNumber: 0,
    notifypostLikesArr: [],
    notifypostOwner: null,
    notifypostOwnerName: null,
    isClientAuth: false,
    chatNotification: 0,
    chatNotificationArr: [],
    openChatNotification: false,
    isIngoingCall: false,
    callerId: '',
    callerName: '',
    expanddNav: false,
    showScheduleForm: false,
    urls: serverUrl,
    defaultAvatar: require('@/assets/avatar.png'),
  }),

  computed: {
    ...mapGetters({
      getUnreadMessage: types.UNREAD_MESSAGE,
      getrerendercomponent: 'getrerendercomponent',
      getAuthAfterLogin: 'getAuthAfterLogin'
    }),

    isAuth() {
      return !!localStorage.getItem("token");
    },

    pho() {
      return this.photo || this.$store.state.photo || this.defaultAvatar;
    },

    posts() {
      return this.$store.getters.getPosts;
    },

    friendRequestlength() {
      return this.$store.getters.getFriendRequestLength || 0;
    },

    userId() {
      return this.$store.state.auth;
    },
  },

  watch: {
    windowWidth(newVal) {
      eventBus.onGlobalResize(newVal);
    },
    keywords: {
      handler(val) {
        if (val && val.trim().length > 0) {
          this.searchUser();
        } else {
          this.searchNewUser = [];
        }
      },
      debounce: 300 // ✅ انتظر 300ms بعد التوقف عن الكتابة
    }
  },

  created() {
    this.initializeAuth();
    this.setupEventBus();
    this.initializeSocket();
    this.loadInitialData();
  },

  mounted() {
    window.addEventListener("resize", this.onResize);
    this.onResize();
  },

  beforeDestroy() {
    window.removeEventListener("resize", this.onResize);
    if (this.socket) this.socket.disconnect();
  },

  methods: {
    // ========== INITIALIZATION ==========
    initializeAuth() {
      axios.get(this.urls + "/check-auth", {
        headers: { authorization: localStorage.getItem("token") }
      }).then((data) => {
        this.isClientAuth = data.data.success;
      });
    },

    setupEventBus() {
      eventBus.$on('change-auth-state-after-login', (authState) => {
        if (authState) {
          this.getUserNameAfterLogin();
          this.$store.dispatch(types.GET_FRIEND_REQUEST_LENGTH);
          this.loadUnreadMessages();
          this.initializeSocket();
          this.$store.dispatch("getPhotoFromServer");
        }
      });

      eventBus.$on("photoChanged", (d) => {
        this.photo = d;
      });
    },

    initializeSocket() {
      if (this.socket) this.socket.disconnect();

      this.socket = io(serverUrl, {
        query: { token: localStorage.getItem("token") }
      });

      this.setupSocketListeners();
    },

    setupSocketListeners() {
      this.socket.on("msg", (msg) => {
        if (this.$route.params.receiverID !== msg.senderId && 
            msg.senderId !== localStorage.getItem('userID')) {
          this.chatNotification++;
          this.chatNotificationArr.push(msg);
        }
      });

      this.socket.on("new-post", (post) => {
        if (localStorage.getItem("userID") !== post.data.post.owner._id) {
          this.postNotificationArr.push(post);
          this.postNotification++;
        }
        this.$store.dispatch("newPost", post);
      });

      this.socket.on("edit-post", (post) => {
        this.$store.commit(types.EDIT_POST, post);
      });

      this.socket.on("delete-post", (post) => {
        this.$store.commit(types.DELETE_POST, post);
      });

      this.socket.on("new-fr-req", (data) => {
        this.$store.commit(types.REQUEST_SOCKET, data);
      });

      this.socket.on("call-request", (data) => {
        this.$nextTick(() => {
          this.isIngoingCall = true;
          this.callerId = data.sender;
          this.callerName = data.name;
        });
      });
    },

    loadInitialData() {
      this.$store.dispatch("getPhotoFromServer");
      this.$store.dispatch(types.GET_FRIEND_REQUEST_LENGTH);
      this.getUserNameAfterLogin();
      this.loadUnreadMessages();
    },

    // ========== API CALLS ==========
    async getUserNameAfterLogin() {
      try {
        const res = await axios.get(this.urls + "/users/get-username", {
          headers: { authorization: localStorage.getItem("token") }
        });
        this.username = res.data;
        this.setUsername(this.username);
      } catch (error) {
        console.error("Error fetching username:", error);
      }
    },

    async loadUnreadMessages() {
      try {
        const res = await axios.get(this.urls + "/get-all-messages/unread-message", {
          headers: { authorization: localStorage.getItem("token") }
        });
        this.chatNotificationArr.push(...res.data.msgs);
        this.chatNotification = res.data.msgs.length;
      } catch (error) {
        console.error("Error loading unread messages:", error);
      }
    },

    // ========== NAVIGATION ==========
    goHome() {
      this.$router.push("/posts").catch(() => {});
    },

    onUsername() {
      const uid = localStorage.getItem("userID");
      this.$router.push({ name: "userProfile", params: { id: uid } }).catch(() => {});
    },

    onFriendRequest() {
      this.$router.push("/friend-requests").catch(() => {});
      this.friendRequestlength = 0;
    },

    // ========== SEARCH ==========
    async searchUser() {
      if (!this.keywords.trim()) return;

      try {
        const res = await axios.post(
          this.urls + "/users/search-user",
          { name: this.keywords },
          { headers: { authorization: localStorage.getItem("token") } }
        );
        if (res.data.success) {
          this.searchNewUser = res.data.users;
        }
      } catch (error) {
        console.error("Search error:", error);
      }
    },

    onSearchNewUSer(id) {
      this.clearSearch();
      this.$router.push("/user/" + id).catch(() => {});
    },

    clearSearch() {
      this.keywords = "";
      this.searchNewUser = [];
    },

    // ========== NOTIFICATIONS ==========
    onNotificationKIcon() {
      this.openPostNotification = !this.openPostNotification;
      this.postNotification = 0;
    },

    onChatNotificationKIcon() {
      this.openChatNotification = !this.openChatNotification;
      this.chatNotification = 0;
    },

    onNotifyPost(post) {
      this.notifypostImage = post.data.post._id;
      this.notifypostName = post.data.post.text;
      this.notifypostId = post.data.post._id;
      this.notifypostCommentsArr = post.data.post.comments;
      this.notifypostLikeNumber = post.data.post.likes.length;
      this.notifypostLikesArr = post.data.post.likes;
      this.notifypostOwner = post.data.post.owner;
      this.notifypostOwnerName = post.data.post.owner.name;

      this.postNotificationArr = this.postNotificationArr.filter(
        p => p.data.post._id !== post.data.post._id
      );

      eventBus.onNavPost(post);
    },

    onNotifyChat(msg, index) {
      console.log(index)
      this.deleteRelatedMessages(msg);

      setTimeout(() => {
        this.$router.replace({
          name: "private-chat",
          params: { receiverID: (msg.senderId || msg.from._id) }
        });
      }, 100);

      this.openChatNotification = false;
    },

    markAllAsRead() {
      this.chatNotificationArr = [];
      this.chatNotification = 0;
    },

    deleteRelatedMessages(msg) {
      const senderId = msg.senderId || msg.from._id;
      if (!senderId) return;

      const filtered = this.chatNotificationArr.filter(notification => {
        const notificationSenderId = notification.senderId || notification.from?._id;
        return notificationSenderId !== senderId;
      });

      this.chatNotificationArr = filtered;
      this.chatNotification = filtered.length;
    },

    // ========== POST CREATION ==========
    openPostDialog() {
       this.dialog = true;
    },

    onFileSelected(event) {
      this.selectedFile = event.target.files[0];
      if (this.selectedFile) {
        this.previewImage = URL.createObjectURL(this.selectedFile);
      }
    },

    async savePost() {
      console.log('!this.selectedFile: ', this.selectedFile)
      if (!this.postText || !this.selectedFile) return;

      const fd = new FormData();
      if (this.selectedFile) {
        fd.append("file", this.selectedFile, this.selectedFile.name);
      }
      fd.append("data", this.postText);

      this.dialog = false;

      try {
        const res = await axios.post(this.urls + "/post/new-post", fd, {
          headers: { authorization: localStorage.getItem("token") }
        });
        this.socket.emit("new-post", res);
        this.resetPostForm();
      } catch (error) {
        console.error("Error saving post:", error);
      }
    },

    resetPostForm() {
      this.postText = "";
      this.selectedFile = null;
      this.previewImage = null;
    },

    // ========== CALL HANDLING ==========
    onAnswer() {
      this.isIngoingCall = false;
      this.socket.emit('start-video', { id: this.callerId });
      this.$router.push({
        name: 'video-call',
        params: { id: this.callerId, name: this.callerName, calle: true }
      });
    },

    onReject() {
      this.isIngoingCall = false;
    },

    // ========== UTILITIES ==========
    upPhoto() {
      this.$store.dispatch("upPhoto");
    },

    logout() {
      localStorage.clear();
      this.$router.push('/login');
      window.location.reload();
    },

    handleImageError(event) {
      if (event.target) {
        event.target.src = this.defaultAvatar;
      }
    },

    onResize() {
      this.windowWidth = window.innerWidth;
    },

    ...mapMutations({
      setUsername: 'setUsername',
      setRenderKey: 'setrerendercomponent'
    }),

    // Helper methods for notifications display
    getSenderName(msg) {
      return msg.senderName || msg.from?.name || 'Unknown User';
    },

    getMessagePreview(msg) {
      if (msg.messageType === 'image') return '📷 Photo';
      if (msg.messageType === 'video') return '🎬 Video';
      if (msg.messageType === 'file') return '📎 File';
      return msg.text?.substring(0, 50) || msg.msg?.substring(0, 50) || 'New message';
    },

    formatTime(timestamp) {
      if (!timestamp) return 'Just now';
      const date = new Date(timestamp);
      const now = new Date();
      const diffMs = now - date;
      const diffMins = Math.floor(diffMs / 60000);

      if (diffMins < 1) return 'Just now';
      if (diffMins < 60) return `${diffMins}m ago`;
      if (diffMins < 1440) return `${Math.floor(diffMins / 60)}h ago`;
      return `${Math.floor(diffMins / 1440)}d ago`;
    }
  }
};
</script>

