  align-items: center;
  z-index: 9999;
  backdrop-filter: blur(8px);
}

.call-modal {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  border-radius: 24px;
  padding: 32px;
  width: 340px;
  max-width: 90%;
  color: white;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
  animation: slideIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
